    // if (v_splitDirection > 0.0 && gl_FragCoord.x < czm_splitPosition) discard;
    if (!czm_splitFragment(v_splitDirection)) {
        discard;
    }
    /* Custom on \u5377\u5E18\u5206\u5C4F\u652F\u6301\u4E0A\u4E0B\u5206\u5272 by qianhy Date in: 2026-06-17 with version 1.135 end */

